    /** Maximum number of people assignable per item (0 = unlimited)
     * @displayOptions.show { /columnType: ["people"] }
     * @default 0
     */
    maxPeopleAllowed?: number | Expression<number>;
    /** The rating scale maximum (3-10)
     * @displayOptions.show { /columnType: ["rating"] }
     * @default 5
     */
