    /** Whether to display dates in a numeric-only format
     * @displayOptions.show { /columnType: ["date"] }
     * @default false
     */
    useNumericOnlyFormat?: boolean | Expression<boolean>;
    /** Number of decimal places to display
     * @displayOptions.show { /columnType: ["numbers"] }
     * @default -1
     */
    precision?: 0 | 1 | 2 | 3 | 4 | 5 | -1 | Expression<number>;
    /** The symbol used to render the rating
     * @displayOptions.show { /columnType: ["rating"] }
     * @default stars
     */
    ratingSymbol?: 'stars' | 'hearts' | Expression<string>;
    /** How the column calculates its value on parent items from their children, on multi-level boards (where these column types roll up by default — pick None to opt out). Each function only works on the column types in its parentheses. Not supported on classic boards.
     * @displayOptions.show { /columnType: ["numbers", "date", "timeline", "status"] }
     */
    rollupFunction?: '' | 'COUNT_KEYS' | 'MAX' | 'MIN' | 'MIN_MAX' | 'NONE' | 'SUM' | Expression<string>;
    /** Whether to display the country flag next to the phone number
     * @displayOptions.show { /columnType: ["phone"] }
     * @default true
     */
    showFlag?: boolean | Expression<boolean>;
    /** Whether to show the year for dates in the current year
     * @displayOptions.show { /columnType: ["date"] }
     * @default false
     */
